from __future__ import annotations

from collections.abc import Iterator, Sequence
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Literal, TypeAlias


@dataclass(slots=True)
class PreExtractedInput:
    """Pre-extracted input that skips the extraction step continues through the pipeline as-is.
    Each individual item represents a separate memory.
    """

    items: list[PreExtractedItem]


@dataclass(slots=True)
class PreExtractedItem:
    """A single pre-extracted memory."""

    content: str
    topic: str


@dataclass(slots=True)
class StringInput:
    """String input to extract memories from."""

    content: str | list[str]
    created_at: str | datetime | None = None
    updated_at: str | datetime | None = None


@dataclass(slots=True)
class ToolCallFuncInput:
    """The function details of an OpenAI-format function tool call."""

    name: str
    arguments: str


@dataclass(slots=True)
class ToolCallCustomInput:
    """The details of an OpenAI-format custom tool call."""

    name: str
    input: str


@dataclass(slots=True)
class ToolCallInput:
    """A single tool call in OpenAI Chat Completions format.

    Set either `function` or `custom` depending on the tool type.
    """

    id: str
    type: str = "function"
    function: ToolCallFuncInput | None = None
    custom: ToolCallCustomInput | None = None


@dataclass(slots=True)
class MessageInput:
    """A message in a conversation using the OpenAI Chat Completions format.

    - 'tool' role (tool results) is mapped to 'user' by the server.
    - 'developer' role is mapped to 'system' by the server.
    """

    role: Literal["user", "assistant", "system", "tool", "developer"]
    content: str = ""
    created_at: str | datetime | None = None
    tool_call_id: str | None = None
    name: str | None = None
    tool_calls: list[ToolCallInput] | None = None


@dataclass(slots=True)
class ConversationInput:
    """Conversation input to extract memories from."""

    messages: list[MessageInput]
    metadata: dict[str, Any] | None = None
    created_at: str | datetime | None = None
    updated_at: str | datetime | None = None


# Type alias for the input_data argument to memories.add()
AddInput: TypeAlias = (
    str | list[dict[str, str]] | PreExtractedInput | ConversationInput | StringInput
)


@dataclass(slots=True)
class VectorRetrieval:
    limit: int | None = None
    retrieval_type: Literal["vector"] = field(default="vector", init=False)


@dataclass(slots=True)
class BM25Retrieval:
    limit: int | None = None
    retrieval_type: Literal["bm25"] = field(default="bm25", init=False)


@dataclass(slots=True)
class HybridRetrieval:
    limit: int | None = None
    retrieval_type: Literal["hybrid"] = field(default="hybrid", init=False)


@dataclass(slots=True)
class FetchRetrieval:
    limit: int | None = None
    retrieval_type: Literal["fetch"] = field(default="fetch", init=False)


NamedRetrievalType: TypeAlias = Literal["vector", "bm25", "hybrid", "fetch"]

RetrievalConfigModel: TypeAlias = VectorRetrieval | BM25Retrieval | HybridRetrieval | FetchRetrieval


@dataclass(slots=True)
class Topic:
    """A topic with an optional per-topic property filter.

    Use ``None`` as a property value to clear an inherited global filter
    for this topic only.
    """

    name: str
    properties: dict[str, str | None] | None = None


TopicSelector: TypeAlias = str | Topic


@dataclass(slots=True)
class Memory:
    id: str
    project_id: str
    content: str
    topic: str
    group: str
    created_at: str
    updated_at: str
    user_id: str | None = None
    tags: list[str] | None = None
    score: float | None = None
    properties: dict[str, str] | None = None


class SearchResults(Sequence[Memory]):
    """List-like wrapper over search results with a total count."""

    def __init__(self, memories: list[Memory], total: int) -> None:
        self._memories = memories
        self.total = total

    def __getitem__(self, index: int) -> Memory:  # type: ignore[override]
        return self._memories[index]

    def __len__(self) -> int:
        return len(self._memories)

    def __iter__(self) -> Iterator[Memory]:
        return iter(self._memories)

    def __repr__(self) -> str:
        return f"SearchResults(total={self.total}, returned={len(self._memories)})"

from dataclasses import dataclass


@dataclass(slots=True)
class Scoping:
    user_scoped: bool
    scope_properties: list[str]


@dataclass(slots=True)
class TopicDetails:
    name: str
    description: str
    is_bounded: bool
    scoping: Scoping


@dataclass(slots=True)
class Group:
    group_id: str
    name: str
    topics: list[TopicDetails]
    scoping: Scoping

from __future__ import annotations

from dataclasses import dataclass, field


@dataclass(slots=True)
class Run:
    """Returned from memories.add() — represents a pipeline run."""

    run_id: str
    status: str
    error: str | None = None


@dataclass(slots=True)
class CommittedOperation:
    memory_id: str
    committed_at: str


@dataclass(slots=True)
class CommittedOperations:
    created: list[CommittedOperation] = field(default_factory=list)
    updated: list[CommittedOperation] = field(default_factory=list)
    deleted: list[CommittedOperation] = field(default_factory=list)


@dataclass(slots=True)
class RunStatus:
    run_id: str
    status: str
    group_id: str
    starting_step: int
    input_type: str
    created_at: str
    updated_at: str
    committed_operations: CommittedOperations | None = None
    error: str | None = None
    user_id: str | None = None

    @property
    def memories_created(self) -> list[CommittedOperation]:
        if self.committed_operations is None:
            return []
        return self.committed_operations.created

    @property
    def memories_updated(self) -> list[CommittedOperation]:
        if self.committed_operations is None:
            return []
        return self.committed_operations.updated

    @property
    def memories_deleted(self) -> list[CommittedOperation]:
        if self.committed_operations is None:
            return []
        return self.committed_operations.deleted

